package com.pulselens.analytics.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.pulselens.analytics.entity.*;import com.pulselens.analytics.repository.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.*;
@RestController @RequestMapping("/api") public class ApiController{
 private final NewsRepository news;private final SocialRepository social;private final UserRepository users;private final AnalysisRepository analyses;private final BookmarkRepository bookmarks;private final SearchRepository searches;private final NotificationRepository notifications;private final ObjectMapper mapper;
 public ApiController(NewsRepository n,SocialRepository s,UserRepository u,AnalysisRepository a,BookmarkRepository b,SearchRepository h,NotificationRepository no,ObjectMapper m){news=n;social=s;users=u;analyses=a;bookmarks=b;searches=h;notifications=no;mapper=m;}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","ok","service","PulseLens API","time",LocalDateTime.now());}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(Authentication a){List<NewsArticle> ns=news.findAll();List<SocialPost> ps=social.findAll();Map<String,Long> sentiment=new LinkedHashMap<>();sentiment.put("Positive",0L);sentiment.put("Neutral",0L);sentiment.put("Negative",0L);Stream.concat(ns.stream().map(NewsArticle::getSentiment),ps.stream().map(SocialPost::getSentiment)).filter(Objects::nonNull).forEach(s->{String k=s.substring(0,1).toUpperCase()+s.substring(1).toLowerCase();if(sentiment.containsKey(k))sentiment.put(k,sentiment.get(k)+1);});List<Map<String,Object>> parts=sentiment.entrySet().stream().map(e->Map.<String,Object>of("name",e.getKey(),"value",e.getValue())).toList();Map<String,Long> dates=new TreeMap<>();ns.stream().filter(n->n.getPublishedAt()!=null).forEach(n->dates.merge(n.getPublishedAt().toLocalDate().toString(),1L,Long::sum));List<Map<String,Object>> activity=dates.entrySet().stream().map(e->Map.<String,Object>of("date",e.getKey().substring(5),"count",e.getValue())).toList();return Map.of("articles",ns.size(),"posts",ps.size(),"topics",trending().size(),"analyses",analyses.countByUserId(uid(a)),"sentiment",Map.of("total",sentiment.values().stream().mapToLong(Long::longValue).sum(),"parts",parts),"activity",activity);}
 @GetMapping("/news") public Map<String,Object> getNews(@RequestParam(required=false)String q,@RequestParam(required=false)String category,@RequestParam(required=false,defaultValue="100")int limit){String query=q==null?"":q.toLowerCase(),cat=category==null?"":category.toLowerCase();List<Map<String,Object>> items=news.findTop100ByOrderByPublishedAtDesc().stream().filter(n->cat.isBlank()||Objects.toString(n.getCategoryName(),"").toLowerCase().contains(cat)).filter(n->query.isBlank()||(Objects.toString(n.getTitle(),"")+" "+Objects.toString(n.getDescription(),"")+" "+Objects.toString(n.getContent(),"")+" "+Objects.toString(n.getSourceName(),"")).toLowerCase().contains(query)).limit(Math.max(1,Math.min(limit,100))).map(this::newsMap).toList();return Map.of("items",items,"count",items.size());}
 @GetMapping("/news/{id}") public ResponseEntity<?> article(@PathVariable Long id){Optional<NewsArticle> found=news.findById(id);if(found.isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(newsMap(found.get()));}
 public record NewsRequest(@NotBlank @Size(max=500)String title,String description,String content,String url,String author,String sourceName,String categoryName,String sentiment,String publishedAt){}
 @PostMapping("/admin/news") public ResponseEntity<?> createNews(@Valid @RequestBody NewsRequest r){NewsArticle n=new NewsArticle();fillNews(n,r);return ResponseEntity.status(201).body(newsMap(news.save(n)));}
 @PutMapping("/admin/news/{id}") public ResponseEntity<?> updateNews(@PathVariable Long id,@Valid @RequestBody NewsRequest r){Optional<NewsArticle> found=news.findById(id);if(found.isEmpty())return ResponseEntity.notFound().build();NewsArticle n=found.get();fillNews(n,r);return ResponseEntity.ok(newsMap(news.save(n)));}
 @DeleteMapping("/admin/news/{id}") public ResponseEntity<?> deleteNews(@PathVariable Long id){if(!news.existsById(id))return ResponseEntity.notFound().build();news.deleteById(id);return ResponseEntity.noContent().build();}
 private void fillNews(NewsArticle n,NewsRequest r){n.setTitle(r.title());n.setDescription(r.description());n.setContent(r.content());n.setUrl(r.url());n.setAuthor(r.author());n.setSourceName(r.sourceName());n.setCategoryName(r.categoryName());n.setSentiment(r.sentiment());try{n.setPublishedAt(r.publishedAt()==null||r.publishedAt().isBlank()?LocalDateTime.now():LocalDateTime.parse(r.publishedAt()));}catch(Exception e){n.setPublishedAt(LocalDateTime.now());}}
 private Map<String,Object> newsMap(NewsArticle n){Map<String,Object> m=new LinkedHashMap<>();m.put("id",n.getId());m.put("title",n.getTitle());m.put("description",n.getDescription());m.put("content",n.getContent());m.put("url",n.getUrl());m.put("author",n.getAuthor());m.put("sourceName",n.getSourceName());m.put("categoryName",n.getCategoryName());m.put("sentiment",n.getSentiment());m.put("publishedAt",n.getPublishedAt());return m;}
 @GetMapping("/social") public Map<String,Object> getSocial(@RequestParam(required=false)String q){String query=q==null?"":q.toLowerCase();List<Map<String,Object>> items=social.findTop100ByOrderByPostedAtDesc().stream().filter(p->query.isBlank()||(Objects.toString(p.getPostText(),"")+" "+Objects.toString(p.getHashtagText(),"")+" "+Objects.toString(p.getAuthorName(),"")).toLowerCase().contains(query)).map(this::socialMap).toList();return Map.of("items",items,"count",items.size());}
 @GetMapping("/social/summary") public Map<String,Object> socialSummary(){List<SocialPost> p=social.findAll();return Map.of("posts",p.size(),"engagement",p.stream().mapToLong(x->x.getLikesCount()+x.getSharesCount()+x.getCommentsCount()).sum(),"platforms",p.stream().map(SocialPost::getPlatform).filter(Objects::nonNull).distinct().count());}
 private Map<String,Object> socialMap(SocialPost p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("platform",p.getPlatform());m.put("authorName",p.getAuthorName());m.put("postText",p.getPostText());m.put("postUrl",p.getPostUrl());m.put("likesCount",p.getLikesCount());m.put("sharesCount",p.getSharesCount());m.put("commentsCount",p.getCommentsCount());m.put("hashtagText",p.getHashtagText());m.put("sentiment",p.getSentiment());m.put("postedAt",p.getPostedAt());return m;}
 @GetMapping("/trending") public List<Map<String,Object>> trending(){Map<String,Long> c=new HashMap<>();news.findAll().forEach(n->countWords(Objects.toString(n.getTitle(),"")+" "+Objects.toString(n.getContent(),""),c));social.findAll().forEach(p->countWords(Objects.toString(p.getPostText(),"")+" "+Objects.toString(p.getHashtagText(),""),c));Set<String> stop=Set.of("the","and","for","with","that","this","from","are","was","were","into","about","have","will","their","they","you","your","can","when","what","how","not","but","all","its","our","using","new","more","than","also");return c.entrySet().stream().filter(e->e.getKey().length()>3&&!stop.contains(e.getKey())).sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(12).map(e->Map.<String,Object>of("topic",e.getKey(),"mentionCount",e.getValue())).toList();}
 private void countWords(String text,Map<String,Long> m){Matcher x=Pattern.compile("[\\p{L}][\\p{L}\\p{N}-]{3,}").matcher(text.toLowerCase());while(x.find())m.merge(x.group(),1L,Long::sum);}
 public record AnalysisRequest(String inputType,@NotBlank @Size(max=100000)String text,List<String> operations){}
 @PostMapping("/analysis") public Map<String,Object> analyze(@Valid @RequestBody AnalysisRequest r,Authentication a)throws Exception{long start=System.nanoTime();String text=r.text();Map<String,Object> out=new LinkedHashMap<>();out.put("inputLength",text.length());List<String> ops=r.operations()==null?List.of("keywords","sentiment","summary"):r.operations();if(ops.contains("keywords")){Map<String,Integer> c=new HashMap<>();Matcher m=Pattern.compile("[\\p{L}][\\p{L}\\p{N}-]{2,}").matcher(text.toLowerCase());while(m.find())c.merge(m.group(),1,Integer::sum);Set<String> stop=Set.of("the","and","for","with","that","this","from","are","was","were","into","about","have","will","their","they","you","your","can","when","what","how","not","but","all","its","our","using","new");out.put("keywords",c.entrySet().stream().filter(e->!stop.contains(e.getKey())).sorted(Map.Entry.<String,Integer>comparingByValue().reversed()).limit(15).map(e->Map.of("word",e.getKey(),"count",e.getValue())).toList());}if(ops.contains("sentiment"))out.put("sentiment",sentiment(text));if(ops.contains("summary"))out.put("summary",summary(text));if(ops.contains("similarity"))out.put("similarity",Map.of("note","Use the LCS lab to compare two strings."));if(ops.contains("patterns"))out.put("patterns",Map.of("textLength",text.length(),"note","Use the CO2 lab to submit a pattern."));out.put("executionMs",(System.nanoTime()-start)/1_000_000);AnalysisRecord rec=new AnalysisRecord();rec.setUserId(uid(a));rec.setAnalysisType(String.join(",",ops));rec.setInputPreview(text.substring(0,Math.min(500,text.length())));rec.setResultJson(mapper.writeValueAsString(out));rec.setExecutionMs(((Number)out.get("executionMs")).longValue());analyses.save(rec);return out;}
 private Map<String,Object> sentiment(String text){String t=text.toLowerCase();Set<String> pos=Set.of("good","great","excellent","improve","success","positive","benefit","helpful","effective","innovative","accessible","responsible","growth","better","support");Set<String> neg=Set.of("bad","poor","fail","negative","harm","risk","danger","problem","worse","crisis","decline","unreliable","error","threat");int p=0,n=0;Matcher m=Pattern.compile("[a-z]+",Pattern.CASE_INSENSITIVE).matcher(t);while(m.find()){if(pos.contains(m.group()))p++;if(neg.contains(m.group()))n++;}int total=p+n;double ps=total==0?0:(double)p/total,ns=total==0?0:(double)n/total,ne=total==0?1:0;return Map.of("label",p>n?"POSITIVE":n>p?"NEGATIVE":"NEUTRAL","positive",ps,"negative",ns,"neutral",ne,"explanation","Lightweight dictionary-based estimate; not a trained sentiment model.");}
 private String summary(String text){String[] s=text.trim().split("(?<=[.!?])\\s+");return s.length<=3?text:String.join(" ",Arrays.copyOf(s,3));}
 @PostMapping("/search-history") public Map<String,Object> addSearch(@RequestBody Map<String,Object> r,Authentication a){SearchRecord s=new SearchRecord();s.setUserId(uid(a));s.setQueryText(Objects.toString(r.get("queryText"),""));s.setResultCount(Integer.parseInt(Objects.toString(r.getOrDefault("resultCount",0))));searches.save(s);return Map.of("message","Search saved");}
 @GetMapping("/search-history") public List<Map<String,Object>> searchHistory(Authentication a){return searches.findTop100ByUserIdOrderBySearchedAtDesc(uid(a)).stream().map(s->Map.<String,Object>of("id",s.getId(),"queryText",s.getQueryText(),"resultCount",s.getResultCount(),"searchedAt",s.getSearchedAt())).toList();}
 @PostMapping("/bookmarks/{articleId}") public ResponseEntity<?> addBookmark(@PathVariable Long articleId,Authentication a){if(!news.existsById(articleId))return ResponseEntity.notFound().build();long u=uid(a);if(bookmarks.findByUserIdAndArticleId(u,articleId).isPresent())return ResponseEntity.ok(Map.of("message","Already bookmarked"));Bookmark b=new Bookmark();b.setUserId(u);b.setArticleId(articleId);bookmarks.save(b);return ResponseEntity.ok(Map.of("message","Bookmarked"));}
 @DeleteMapping("/bookmarks/{articleId}") public ResponseEntity<?> removeBookmark(@PathVariable Long articleId,Authentication a){bookmarks.findByUserIdAndArticleId(uid(a),articleId).ifPresent(bookmarks::delete);return ResponseEntity.noContent().build();}
 @GetMapping("/bookmarks") public List<Map<String,Object>> getBookmarks(Authentication a){return bookmarks.findByUserIdOrderByCreatedAtDesc(uid(a)).stream().map(b->news.findById(b.getArticleId()).map(this::newsMap).orElse(null)).filter(Objects::nonNull).toList();}
 @GetMapping("/analysis-history") public List<Map<String,Object>> analysisHistory(Authentication a){return analyses.findTop100ByUserIdOrderByCreatedAtDesc(uid(a)).stream().map(x->Map.<String,Object>of("id",x.getId(),"analysisType",x.getAnalysisType(),"inputPreview",Objects.toString(x.getInputPreview(),""),"executionMs",x.getExecutionMs(),"createdAt",x.getCreatedAt())).toList();}
 @GetMapping("/notifications") public List<Map<String,Object>> getNotifications(Authentication a){return notifications.findTop100ByUserIdOrderByCreatedAtDesc(uid(a)).stream().map(n->Map.<String,Object>of("id",n.getId(),"title",n.getTitle(),"message",n.getMessage(),"readFlag",n.isReadFlag(),"createdAt",n.getCreatedAt())).toList();}
 @PostMapping("/notifications/{id}/read") public ResponseEntity<?> readNotification(@PathVariable Long id,Authentication a){Optional<UserNotification> found=notifications.findByIdAndUserId(id,uid(a));if(found.isEmpty())return ResponseEntity.notFound().build();UserNotification n=found.get();n.setReadFlag(true);notifications.save(n);return ResponseEntity.ok(Map.of("message","Marked read"));}
 @GetMapping("/admin/users") public List<Map<String,Object>> adminUsers(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.getId(),"fullName",u.getFullName(),"username",u.getUsername(),"email",u.getEmail(),"role",u.getRole(),"createdAt",u.getCreatedAt())).toList();}
 public record AssistantRequest(@NotBlank @Size(max=1000) String question){}
 @PostMapping("/assistant") public Map<String,Object> assistant(@Valid @RequestBody AssistantRequest r){String q=r.question().toLowerCase();Set<String> terms=Arrays.stream(q.split("[^\\p{L}\\p{N}]+" )).filter(x->x.length()>2).collect(Collectors.toSet());List<NewsArticle> matches=news.findTop100ByOrderByPublishedAtDesc().stream().filter(n->{String hay=(Objects.toString(n.getTitle(),"")+" "+Objects.toString(n.getDescription(),"")+" "+Objects.toString(n.getContent(),"")).toLowerCase();return terms.stream().anyMatch(hay::contains);}).limit(5).toList();List<Map<String,Object>> sources=matches.stream().map(n->Map.<String,Object>of("id",n.getId(),"title",n.getTitle(),"sourceName",Objects.toString(n.getSourceName(),"Unknown source"),"publishedAt",n.getPublishedAt()==null?"":n.getPublishedAt().toString(),"excerpt",Objects.toString(n.getDescription(),Objects.toString(n.getContent(),"")).substring(0,Math.min(240,Objects.toString(n.getDescription(),Objects.toString(n.getContent(),"")).length())))).toList();String answer=matches.isEmpty()?"I could not find matching articles in the current database. Try a different phrase, or add/import more content. This assistant only searches the workspace records and does not access the whole internet.":"I found "+matches.size()+" matching article record(s) in your workspace. The most relevant stored records are listed below. Review their excerpts and sources before drawing conclusions.";return Map.of("question",r.question(),"answer",answer,"sources",sources,"sourceMode","local database search");}
 private long uid(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}
}
